<script lang="ts">
 import HelpTip from './HelpTip.svelte';
 import CardLinkOptions from './CardLinkOptions.svelte';
 import {onMount,onDestroy,tick} from 'svelte';
 import {page} from '$app/stores';
 import {api} from '$lib/api';
 import ProseEditor from './ProseEditor.svelte';
 import {goto} from '$app/navigation';
 import StyleLibrary from './StyleLibrary.svelte';
 import StyleControls from './StyleControls.svelte';
 import Markdown from './Markdown.svelte';
 import {wordDiff} from '$lib/subplot-diff';
 export let onValidateTurningPoints:()=>Promise<void>=async()=>{};
 export let chatBusy=false;
 export let onDraftScene:()=>Promise<void>=async()=>{};
 export async function refreshDraft(){await refresh();editorKey++;}
 export let navigationTarget:HTMLElement|undefined;
 export let onSelection:(value:any)=>void=()=>{};
 let editorTab='prose',activeTurningPoint='',workOpen=false,addingScene=false,newScenePurpose='',newSceneTpId='';
 $: onSelection({subplot,element,busy});
 function navigation(node:HTMLElement,target:HTMLElement|undefined){const move=(host:HTMLElement|undefined)=>{if(host&&node.parentElement!==host)host.appendChild(node);};move(target);return {update:move,destroy(){node.remove();}};}
 let savedPremise='';
 const premiseValues=()=>subplot?JSON.stringify([subplot.title,subplot.premise,subplot.theme,subplot.start_state,subplot.end_state]):'';
 const normalizedLinks=(cards:any[])=>cards.map(c=>({card_id:c.card_id||null,name:c.card_id?null:c.name,type:c.card_id?null:c.type,role:c.role,secret_action:c.secret_action||null}));
 export async function flush(){await editor?.flush();if(subplot&&savedPremise&&premiseValues()!==savedPremise)await savePremise();if(element){const changed=purpose!==element.purpose||Number(targetLength)!==element.target_length||timeMarker!==element.time_marker||(tpId||null)!==element.turning_point_id||JSON.stringify(normalizedLinks(cardLinks))!==JSON.stringify(normalizedLinks(element.cards));if(changed){element=await api(`/elements/${element.scene_id}`);await saveSpec();}}}
 export async function rename(title:string){await flush();if(element)await api(`/cards/${element.scene_id}`,'PATCH',{title,baseRev:element.rev});else if(subplot){subplot.title=title;await savePremise();}await refresh();}

 // Each view swap starts at the top; otherwise the previous view's scroll offset strands the reader mid-page.
 function toTop(){document.querySelector('.scroll')?.scrollTo({top:0});}
 async function readPlot(){await openOverview();await refresh();readingPlot=true;outlineOpen=false;toTop();}
 async function startScene(turningPointId=''){await flush();newSceneTpId=turningPointId;elementTitle='';newScenePurpose='';addingScene=true;}
 async function openTurningPoint(id:string){await flush();readingPlot=false;element=null;review=null;activeTurningPoint=id;workOpen=false;toTop();}
 export async function openOverview(){await flush();readingPlot=false;element=null;review=null;activeTurningPoint='';workOpen=false;toTop();if($page.url.searchParams.has('element')){loadedElement='';await goto(`/n/${novelId}/plots?subplot=${selected}`,{keepFocus:true,noScroll:true});}}
 export async function showWork(){await flush();readingPlot=false;workOpen=true;toTop();}
 $: novelId=$page.params.novelId;

 let plots:any[]=[],subplot:any=null,selected='',element:any=null,allCards:any[]=[],work:any={change_sets:[],proposals:[],extractions:[],requests:[]};
 let error='',notice='',busy=false,newTitle='',newPremise='',tpText='',elementTitle='',tpId='',purpose='',targetLength=1200,timeMarker='',summary='',cardLinks:any[]=[],addCardId='',newCardName='',newCardType='character',newCardRole='on_stage';
 let editor:ProseEditor|undefined,editorKey=0,review:any=null,impactRows:any[]=[],impactSelection:string[]=[],impactCard='',impactTitle='',proposals:Record<string,any>={},extractionChoices:Record<string,any[]>={},requestContext='',linkTarget='',linkType='depends_on',linked:any[]=[],mentionData:any={missing:[],mentions:[]},collapsed:string[]=[],showHistory=true,filterCard='';
 let outlineOpen=true,readingPlot=false;
 let libraryOpen=false;
 let ready=false,loadedSubplot='',loadedElement='';
 function syncElementRoute(eid:string,subplotId:string){if(subplotId!==selected||eid===loadedElement)return;loadedElement=eid;const target=subplot?.elements.find((e:any)=>e.scene_id===eid);if(target&&element?.scene_id!==eid)void run(()=>pickElement(target));else if(!eid&&element)void run(openOverview);}
 $: if(ready)syncElementRoute($page.url.searchParams.get('element')||'',$page.url.searchParams.get('subplot')||'');
 $: if(ready&&$page.url.searchParams.get('subplot')&&loadedSubplot!==$page.url.searchParams.get('subplot')){loadedSubplot=$page.url.searchParams.get('subplot')!;void run(()=>pick(loadedSubplot));}
 let poll:ReturnType<typeof setInterval>;
 const run=async(fn:()=>Promise<void>)=>{busy=true;error='';notice='';try{await fn();}catch(e:any){error=e.message;}finally{busy=false;}};
 async function refresh(){plots=await api(`/novels/${novelId}/subplots`);allCards=await api(`/novels/${novelId}/cards`);work=await api(`/novels/${novelId}/subplot-work?${new URLSearchParams({...selected?{subplot_id:selected}:{},...filterCard?{card_id:filterCard}:{}})}`);if(selected){subplot=await api(`/subplots/${selected}`);savedPremise=premiseValues();}if(element){element=await api(`/elements/${element.scene_id}`);summary=element.summary;mentionData=await api(`/elements/${element.scene_id}/mentions`);linked=await api(`/elements/${element.scene_id}/links`);}if(review)review=await api(`/change-sets/${review.id}`);for(const p of work.proposals)if(!proposals[p.id])proposals[p.id]=structuredClone(p.payload);for(const x of work.extractions)if(!extractionChoices[x.id])extractionChoices[x.id]=x.payload.entities.map((ent:any,index:number)=>({index,action:'accept',name:ent.name,body:ent.body,target_id:ent.card_id||''}));}
 async function pick(id:string){await flush();readingPlot=false;subplot=await api(`/subplots/${id}`);selected=subplot.id;if(id!==selected){loadedSubplot=selected;await goto(`/n/${novelId}/plots?subplot=${selected}`,{replaceState:true});}element=null;review=null;activeTurningPoint='';workOpen=false;outlineOpen=false;await refresh();const routeElement=$page.url.searchParams.get('element');if(routeElement&&$page.url.searchParams.get('subplot')===id){const target=subplot.elements.find((e:any)=>e.scene_id===routeElement);if(target){loadedElement=routeElement;await pickElement(target);}}}
 async function pickElement(e:any){await flush();readingPlot=false;element=await api(`/elements/${e.scene_id}`);purpose=element.purpose;targetLength=element.target_length;timeMarker=element.time_marker;tpId=element.turning_point_id||'';summary=element.summary;cardLinks=element.cards.map((c:any)=>({...c}));mentionData=await api(`/elements/${element.scene_id}/mentions`);linked=await api(`/elements/${element.scene_id}/links`);review=null;activeTurningPoint='';workOpen=false;editorTab='prose';outlineOpen=false;toTop();if($page.url.searchParams.get('element')!==e.scene_id){loadedElement=e.scene_id;await goto(`/n/${novelId}/plots?subplot=${selected}&element=${e.scene_id}`,{keepFocus:true,noScroll:true});}await tick();if(window.innerWidth<760)document.querySelector('main')?.scrollIntoView();}
 function moveProposal(items:any[],index:number,direction:number){const j=index+direction;if(j>=0&&j<items.length)[items[index],items[j]]=[items[j],items[index]];proposals={...proposals};}
 async function create(){const p=await api(`/novels/${novelId}/subplots`,'POST',{title:newTitle,premise:newPremise});newTitle='';newPremise='';await refresh();await pick(p.id);}
 async function savePremise(){await api(`/subplots/${selected}`,'PATCH',{title:subplot.title,premise:subplot.premise,theme:subplot.theme,start_state:subplot.start_state,end_state:subplot.end_state,baseRev:subplot.rev});await refresh();}
 async function approvePremise(){await savePremise();await api(`/subplots/${selected}/approve`,'POST',{baseRev:subplot.rev});await refresh();}
 async function generate(kind:string){await editor?.flush();await api(`/subplots/${selected}/generate`,'POST',{kind,idea:newPremise||subplot.premise,turning_point_id:tpId||null});await refresh();}
 async function saveSpec(){await api(`/elements/${element.scene_id}/spec`,'PUT',{baseVersion:element.version,purpose,target_length:Number(targetLength),time_marker:timeMarker,turning_point_id:tpId||null,cards:cardLinks});await refresh();cardLinks=element.cards.map((c:any)=>({...c}));}
 async function approveSpec(){await saveSpec();await api(`/elements/${element.scene_id}/approve`,'POST',{baseVersion:element.version});await refresh();}
 async function reorder(kind:string,id:string,direction:number){const items=kind==='turning_points'?subplot.turning_points:subplot.elements;const ids=items.map((x:any)=>x.id||x.scene_id);const i=ids.indexOf(id),j=i+direction;if(j<0||j>=ids.length)return;[ids[i],ids[j]]=[ids[j],ids[i]];await api(`/subplots/${selected}/reorder`,'POST',{kind,ids,baseRev:subplot.rev});await refresh();}
 async function resolve(action:string,hunkIds?:string[],elementId?:string){await editor?.flush();const result=await api(`/change-sets/${review.id}/resolve`,'POST',{action,hunkIds,elementId});if(result.metadata_errors?.length)notice='Changes saved. Some metadata needs retry: '+result.metadata_errors.join('; ');await refresh();editorKey++;}
 async function openImpact(id:string){impactCard=id;const c=allCards.find(c=>c.id===id);impactTitle=c?.title+': '+(c?.body?.replace(/\s+/g,' ').slice(0,65)||'revised');impactRows=await api(`/cards/${id}/impact`);impactSelection=impactRows.filter(r=>r.role==='on_stage').map(r=>r.element_id);}
 async function proposeRewrite(){const set=await api(`/novels/${novelId}/change-sets`,'POST',{cause_type:'card_edit',cause_ref:impactCard,title:impactTitle,element_ids:impactSelection});impactCard='';review=set;workOpen=true;await refresh();}

 function label(c:any){return c.title||c.name||allCards.find(x=>x.id===c.card_id)?.title||c.card_id;}
 onMount(()=>{void run(async()=>{await refresh();const p=$page.url.searchParams.get('subplot');if(p&&plots.some(x=>x.id===p)){loadedSubplot=p;await pick(p);}ready=true;const eid=$page.url.searchParams.get('element');loadedElement=eid||'';if(eid&&subplot?.elements.some((e:any)=>e.scene_id===eid))await pickElement(subplot.elements.find((e:any)=>e.scene_id===eid));const c=$page.url.searchParams.get('impact');if(c)await openImpact(c);if($page.url.searchParams.has('work'))workOpen=true;});poll=setInterval(()=>{if(work.change_sets.some((s:any)=>s.run_status==='running'))void run(refresh);else if(element&&!summary){const id=element.scene_id;void api(`/elements/${id}`).then(e=>{if(element?.scene_id===id){element={...element,summary:e.summary};summary=e.summary;}}).catch(()=>{});}},3000);});
 onDestroy(()=>clearInterval(poll));
</script>

<div class="subplot-app embedded">
 {#if error}<div class="alert" role="alert">{error}</div>{/if}{#if notice}<p role="status">{notice}</p>{/if}{#if busy}<p class="busy" role="status">Working…</p>{/if}
 <div class="layout">
 <aside class="embedded-nav" use:navigation={navigationTarget} aria-label="Plot contents"><label>Plot<select aria-label="Switch plot" value={selected} on:change={(ev)=>{const id=ev.currentTarget.value;void run(async()=>{await flush();await goto(`/n/${novelId}/plots?subplot=${id}`);});}}><option value="">Choose plot…</option>{#each plots as p}<option value={p.id}>{p.title}</option>{/each}</select></label>
 {#if subplot}<button class="step" on:click={()=>run(openOverview)}>Plot overview<small>Premise · {subplot.status.replaceAll('_',' ')}</small></button><button class="step" class:active={readingPlot} disabled={busy||!subplot.elements.length} on:click={()=>run(readPlot)}>Read whole plot</button><div class="scene-heading"><b>Scenes · {subplot.elements.length}</b><small>{subplot.elements.reduce((n:number,e:any)=>n+(e.prose?.word_count||0),0).toLocaleString()} words</small></div>
 <nav aria-label="Plot scenes">{#each subplot.elements as e,i}<div class="outline-row"><button class:active={element?.scene_id===e.scene_id} aria-current={element?.scene_id===e.scene_id?'page':undefined} on:click={()=>run(()=>pickElement(e))}><span>{i+1}. {e.title}</span><small>{e.status.replaceAll('_',' ')} · {e.prose.word_count} words</small></button><div class="scene-order"><button aria-label={'Move '+e.title+' up'} disabled={i===0||subplot.elements[i-1]?.turning_point_id!==e.turning_point_id} on:click={()=>run(()=>reorder('elements',e.scene_id,-1))}>↑</button><button aria-label={'Move '+e.title+' down'} disabled={i===subplot.elements.length-1||subplot.elements[i+1]?.turning_point_id!==e.turning_point_id} on:click={()=>run(()=>reorder('elements',e.scene_id,1))}>↓</button></div></div>{/each}</nav>
 <button class="chip" disabled={busy||subplot.status!=='approved'} on:click={()=>run(()=>startScene())}>+ Add scene</button>{#if subplot.status!=='approved'}<small>Approve the premise in Plot overview to add scenes.</small>{:else if !subplot.elements.length}<small>Add your first scene, then open Plan or Prose to develop it.</small>{/if}
 {#if subplot.turning_points.length}<div class="scene-heading"><b>Turning points · {subplot.turning_points.length}</b></div><nav aria-label="Turning points">{#each subplot.turning_points as tp,i (tp.id)}<div class="turning-point-row"><button class="step tp-nav" class:active={activeTurningPoint===tp.id} aria-current={activeTurningPoint===tp.id?'page':undefined} on:click={()=>run(()=>openTurningPoint(tp.id))}><span>{tp.text}</span><small><span class="status s-{tp.status}">{tp.status.replaceAll('_',' ')}</span></small></button><div class="turning-point-order"><button aria-label={'Move turning point '+(i+1)+' up'} title="Move turning point up" disabled={busy||i===0} on:click={()=>run(()=>reorder('turning_points',tp.id,-1))}>↑</button><button aria-label={'Move turning point '+(i+1)+' down'} title="Move turning point down" disabled={busy||i===subplot.turning_points.length-1} on:click={()=>run(()=>reorder('turning_points',tp.id,1))}>↓</button></div></div>{/each}</nav><button class="validate-tps" disabled={busy||chatBusy} on:click={()=>run(onValidateTurningPoints)}>Validate turning points</button>{/if}{/if}
 <hr/><button class="step" on:click={()=>run(showWork)}>Review & history</button>
 </aside>
 <div class="subplot-content"><fieldset disabled={busy}>
 {#if subplot&&readingPlot}<div class="actions reader-actions"><button class="back" on:click={()=>run(openOverview)}>← Back to plot overview</button><small>{subplot.elements.length} scenes · {subplot.elements.reduce((n:number,e:any)=>n+(e.prose?.word_count||0),0).toLocaleString()} words</small></div><article class="reading" aria-label="Read whole plot">{#each subplot.elements as scene (scene.scene_id)}<section class="reader-scene"><h3>{scene.title}<button on:click={()=>run(()=>pickElement(scene))}>Edit</button></h3>{#if scene.prose?.text?.trim()}{#each scene.prose.text.split(/\n\s*\n/) as paragraph}<p>{paragraph}</p>{/each}{:else}<p class="gap">Not drafted yet.</p>{/if}</section>{/each}</article>{/if}
 {#if subplot&&!readingPlot&&!element&&!review&&!activeTurningPoint&&!workOpen}<section><div class="scene-heading"><h2>Premise <HelpTip term="Premise" text="A short description of what this plot is about: who is involved, what happens, and what is at stake. Approve it before adding scenes or asking for scene plans."/></h2><span class="status s-{subplot.status}">{subplot.status.replaceAll('_',' ')}</span></div><p class="note">Describe what this plot is about, then approve the premise and develop its scenes.</p><label>Premise <HelpTip term="Premise" text="A short description of what this plot is about: who is involved, what happens, and what is at stake. Approve it before adding scenes or asking for scene plans."/><textarea class="writing" rows="9" bind:value={subplot.premise}></textarea></label><details open={!!(subplot.theme||subplot.start_state||subplot.end_state)}><summary>Theme and start / end states</summary><label>Theme <HelpTip term="Theme" text="The underlying idea or question this plot explores. For example: Does creating conscious minds give a civilization responsibility for their freedom? Optional; included in AI plot and scene context."/><input bind:value={subplot.theme}/></label><div class="pair"><label>Start state <HelpTip term="Start state" text="The situation at the beginning of this plot: what the characters believe, want, or control. For example: The Shi-yul-pa depend on digital minds they treat as tools."/><textarea bind:value={subplot.start_state}></textarea></label><label>End state <HelpTip term="End state" text="The situation this plot should reach. Describe what has changed by its end; this gives the AI a destination when developing scenes."/><textarea bind:value={subplot.end_state}></textarea></label></div></details><div class="actions">{#if subplot.status!=='approved'}<button class="primary" disabled={busy} on:click={()=>run(approvePremise)}>Approve premise</button>{/if}<button disabled={busy} on:click={()=>run(savePremise)}>Save premise</button><button disabled={busy} on:click={()=>run(()=>generate('premise'))}>Help develop the premise</button></div></section>
 <section><div class="scene-heading"><h2>Turning points <HelpTip term="Turning points" text="Major events, decisions, or discoveries that change the plot’s direction. They are optional groups for scenes, rather than the scenes themselves."/></h2><button disabled={busy||subplot.status!=='approved'} on:click={()=>run(async()=>{await generate('turning_points');workOpen=true;toTop();})}>Suggest turning points</button></div><p class="note">Optional. Turning points organize a longer plot; scenes can also sit directly under the plot.</p>{#if subplot.turning_points.length}<ol class="tp-list">{#each subplot.turning_points as tp,i (tp.id)}<li><div class="turning-point-row"><button class="tp-row" on:click={()=>run(()=>openTurningPoint(tp.id))}><span>{tp.text}</span><small><span class="status s-{tp.status}">{tp.status.replaceAll('_',' ')}</span> {subplot.elements.filter((e:any)=>e.turning_point_id===tp.id).length} scenes</small></button><div class="turning-point-order"><button aria-label={'Move turning point '+(i+1)+' up'} title="Move turning point up" disabled={busy||i===0} on:click={()=>run(()=>reorder('turning_points',tp.id,-1))}>↑</button><button aria-label={'Move turning point '+(i+1)+' down'} title="Move turning point down" disabled={busy||i===subplot.turning_points.length-1} on:click={()=>run(()=>reorder('turning_points',tp.id,1))}>↓</button></div></div>{#if tp.status==='needs_review'}<div class="tp-review"><button disabled={busy||subplot.status!=='approved'} aria-label={'Still fine: '+tp.text} on:click={()=>run(async()=>{await api(`/turning-points/${tp.id}/approve`,'POST',{baseRev:tp.rev});await refresh();})}>Still fine</button></div>{/if}</li>{/each}</ol><div class="actions"><button class="validate-tps" disabled={busy||chatBusy} on:click={()=>run(onValidateTurningPoints)}>Validate turning points</button></div><p class="note">Get feedback in chat on the arc, decisions, and what needs sharpening.</p>{/if}<label>New turning point<textarea bind:value={tpText} placeholder="What changes, and for whom?"></textarea></label><button class="primary" disabled={busy||!tpText.trim()||subplot.status!=='approved'} on:click={()=>run(async()=>{await api(`/subplots/${selected}/turning-points`,'POST',{text:tpText});tpText='';await refresh();})}>Add turning point</button></section>
 <section><div class="scene-heading"><h2>Scenes</h2><div class="actions"><button disabled={busy||!subplot.elements.length} on:click={()=>run(readPlot)}>Read whole plot</button><button class="primary" disabled={busy||subplot.status!=='approved'} on:click={()=>run(()=>startScene())}>+ Add scene</button></div></div>{#if subplot.status!=='approved'}<p class="note">Approve the premise above to start adding scenes.</p>{:else if !subplot.elements.length}<p class="note">Add a scene, describe what happens in its Plan, then write it in Prose or ask AI for a draft.</p>{/if}<div class="grid">{#each subplot.elements as e}<button class="card" on:click={()=>run(()=>pickElement(e))}><span class="kind"><span class="status s-{e.status}">{e.status.replaceAll('_',' ')}</span><span>{e.prose.word_count} words</span></span><span class="ttl">{e.title}</span><span class="snip">{e.purpose||'Open this scene to plan and write it.'}</span></button>{/each}</div><div class="ai-row"><label>Suggest scene plans for<select bind:value={tpId}><option value="">The whole plot</option>{#each subplot.turning_points as tp}<option value={tp.id}>{tp.text}</option>{/each}</select></label><button disabled={busy||subplot.status!=='approved'} on:click={()=>run(async()=>{await generate('specs');workOpen=true;toTop();})}>Suggest scene plans</button></div></section>{/if}
 {#if activeTurningPoint&&!workOpen&&!review}{@const tp=subplot?.turning_points.find((t:any)=>t.id===activeTurningPoint)}{#if tp}<section><button class="back" on:click={()=>run(openOverview)}>← Plot overview</button><div class="scene-heading"><h2>Turning point <HelpTip term="Turning point" text="A major event, decision, or discovery that changes the direction of the plot. Group scenes beneath it to show how that change happens. Scenes may also sit directly under the plot."/></h2><span class="status s-{tp.status}">{tp.status.replaceAll('_',' ')}</span></div><label>Turning point <HelpTip term="Turning point" text="A major event, decision, or discovery that changes the direction of the plot. Group scenes beneath it to show how that change happens. Scenes may also sit directly under the plot."/><textarea class="writing" value={tp.text} on:change={(ev)=>{const text=ev.currentTarget.value;void run(async()=>{await api(`/turning-points/${tp.id}`,'PATCH',{text,baseRev:tp.rev});await refresh();});}}></textarea></label><div class="actions"><button class="primary" on:click={()=>run(async()=>{await api(`/turning-points/${tp.id}/approve`,'POST',{baseRev:tp.rev});await refresh();})}>{tp.status==='needs_review'?'Still fine':'Approve'}</button><button disabled={busy||subplot.turning_points[0]?.id===tp.id} on:click={()=>run(()=>reorder('turning_points',tp.id,-1))}>↑ Move up</button><button disabled={busy||subplot.turning_points.at(-1)?.id===tp.id} on:click={()=>run(()=>reorder('turning_points',tp.id,1))}>↓ Move down</button><button class="danger" on:click={()=>run(async()=>{await api(`/turning-points/${tp.id}`,'DELETE',{baseRev:tp.rev});activeTurningPoint='';await refresh();})}>Delete turning point</button><button disabled={busy||!subplot.elements.some((e:any)=>e.turning_point_id===tp.id)} on:click={()=>run(async()=>{review=await api(`/novels/${novelId}/change-sets`,'POST',{cause_type:'turning_point_edit',cause_ref:tp.id,title:'Turning point: '+tp.text.slice(0,50),element_ids:subplot.elements.filter((e:any)=>e.turning_point_id===tp.id).map((e:any)=>e.scene_id)});workOpen=true;await refresh();})}>Propose scene rewrites</button></div><p class="note">Proposes changes to scene prose under this turning point. Add scenes first to enable rewrites.</p>{#if tp.review_reason}<p class="alert">{tp.review_reason}</p>{/if}<div class="scene-heading"><h3>Scenes</h3><button class="primary" disabled={busy||subplot.status!=='approved'} on:click={()=>run(()=>startScene(tp.id))}>+ Add scene</button></div><div class="grid">{#each subplot.elements.filter((e:any)=>e.turning_point_id===tp.id) as e}<button class="card" on:click={()=>run(()=>pickElement(e))}><span class="kind"><span class="status s-{e.status}">{e.status.replaceAll('_',' ')}</span><span>{e.prose.word_count} words</span></span><span class="ttl">{e.title}</span><span class="snip">{e.purpose}</span></button>{:else}<p class="note">No scenes under this turning point yet. Add a scene here to get started.</p>{/each}</div></section>{/if}{/if}
 {#if element&&!review&&!workOpen}<div class="editor-tabs" role="tablist" aria-label="Scene editor"><button role="tab" aria-selected={editorTab==='plan'} on:click={()=>editorTab='plan'}>Plan</button><button role="tab" aria-selected={editorTab==='prose'} on:click={()=>editorTab='prose'}>Prose</button></div><section hidden={editorTab!=='plan'}><h2>Scene plan</h2><p class="note">Describe what happens here. Approve the plan to draft with AI, or switch to Prose and write it yourself.</p><p class="states">Plan <span class="status s-{element.status}">{element.status.replaceAll('_',' ')}</span> Prose <span class="status s-{element.prose_state}">{element.prose_state.replaceAll('_',' ')}</span></p>{#if element.review_reason}<p class="alert">{element.review_reason}<button on:click={()=>run(async()=>{await api(`/elements/${element.scene_id}/approve`,'POST',{baseVersion:element.version});await refresh();})}>Still fine</button></p>{/if}
 <details open><summary>Scene details</summary><label>Purpose <HelpTip term="Purpose" text="What happens in this scene and why it matters: a discovery, conflict, decision, or change. Used to guide AI drafting."/><textarea class="writing" bind:value={purpose}></textarea></label><div class="pair"><label>Target words <HelpTip term="Target words" text="The approximate desired length of this scene. Guides AI drafting; it does not limit how much you can write."/><input type="number" min="1" bind:value={targetLength}/></label><label>Time marker <HelpTip term="Time marker" text="An optional free-text note about when this scene happens, such as Three days after the uprising or Meanwhile, on the 5th Planet. Included in AI scene context; it does not automatically reorder scenes."/><input bind:value={timeMarker}/></label></div><label>Turning point <HelpTip term="Turning point" text="A major event, decision, or discovery that changes the direction of the plot. Group scenes beneath it to show how that change happens. Scenes may also sit directly under the plot."/><select bind:value={tpId}><option value="">Under premise</option>{#each subplot.turning_points as tp}<option value={tp.id}>{tp.text}</option>{/each}</select></label>
 {#each cardLinks as c,i}<div class="card-link"><span>{label(c)}</span><HelpTip term="Card role" text="On stage means directly present or involved in this scene. Referenced means mentioned or relevant without being directly present. This helps choose the card context sent to the AI."/><select aria-label={'Role of '+label(c)} bind:value={c.role}><option value="on_stage">On stage</option><option value="referenced">Referenced</option></select>{#if (c.type||allCards.find(x=>x.id===c.card_id)?.type)==='secret'}<HelpTip term="Secret action" text="Track what this scene does with a secret: introduced brings it into the story, hinted offers clues, and revealed discloses it. No action leaves its disclosure unchanged."/><select aria-label="Secret action" bind:value={c.secret_action}><option value={null}>No action</option><option value="introduced">Introduced</option><option value="hinted">Hinted</option><option value="revealed">Revealed</option></select>{/if}<button aria-label={'Remove '+label(c)} on:click={()=>cardLinks=cardLinks.filter((_,j)=>j!==i)}>×</button></div>{/each}
 <label>Link existing card <HelpTip term="Link existing card" text="Connect an existing character, group, location, object, or secret to this scene. Linked cards supply story facts to AI scene context."/><select bind:value={addCardId}><option value="">Choose a card</option><CardLinkOptions cards={allCards.filter(c=>['character','group','setting','object','secret'].includes(c.type)&&!cardLinks.some(x=>x.card_id===c.id))}/></select></label><button disabled={!addCardId} on:click={()=>{cardLinks=[...cardLinks,{card_id:addCardId,role:'on_stage'}];addCardId='';}}>Link card</button>
 <details><summary>New draft card <HelpTip term="New draft card" text="Add a placeholder for a character, group, location, object, or secret needed by this scene. Add to spec puts it in the scene plan. Saving the plan creates and links the card, or reuses a matching one. This is a reference card, not scene prose."/></summary><label>Name<input bind:value={newCardName}/></label><label>Type<select bind:value={newCardType}>{#each ['character','group','setting','object','secret'] as type}<option value={type}>{type==='setting'?'location':type}</option>{/each}</select></label><button disabled={!newCardName.trim()} on:click={()=>{cardLinks=[...cardLinks,{name:newCardName,type:newCardType,role:'on_stage'}];newCardName='';}}>Add to spec</button></details>
 <div class="actions"><button class="primary" disabled={busy} on:click={()=>run(approveSpec)}>Save &amp; approve plan</button><button disabled={busy} on:click={()=>run(saveSpec)}>Save plan</button></div></details></section>
 <section hidden={editorTab!=='prose'}><h2>Write this scene</h2><p class="note">Write directly in the editor below, or use AI to propose a draft. AI drafts wait for your approval in Review.</p>{#if element.status!=='approved'}<p class="note">To draft with AI, open Plan and choose Save &amp; approve plan first.</p>{/if}<div class="actions"><button class:primary={element.status==='approved'} disabled={busy||chatBusy||element.status!=='approved'} on:click={()=>run(async()=>{await flush();await onDraftScene();})}>Draft scene with AI</button><button disabled={busy} on:click={()=>run(async()=>{await editor?.flush();await refresh();await api(`/elements/${element.scene_id}/approve-prose`,'POST',{baseVersion:element.version});await refresh();})}>Approve prose & extract cards</button><button disabled={busy} on:click={()=>run(async()=>{await editor?.flush();await api(`/elements/${element.scene_id}/extract`,'POST',{});await refresh();})}>Extract cards again</button></div>{#key element.scene_id+':'+editorKey}<ProseEditor bind:this={editor} sceneId={element.scene_id} onSaved={()=>{const id=element?.scene_id,plotId=selected;if(id)void api(`/elements/${id}`).then(e=>{if(element?.scene_id===id)element=e;if(subplot&&selected===plotId)subplot={...subplot,elements:subplot.elements.map((item:any)=>item.scene_id===id?e:item)};});}}/>{/key}
 <div class="tools">
 <label>Rolling summary <HelpTip term="Rolling summary" text="A short factual recap of this scene’s written events. Used as compact context for other scenes and plot chat. Keep it current so the AI knows what has actually happened."/><textarea rows="3" bind:value={summary}></textarea></label><button on:click={()=>run(async()=>{await api(`/elements/${element.scene_id}/summary`,'PUT',{summary,baseVersion:element.version});await refresh();})}>Save summary</button></div>
 {#each mentionData.missing as c}<p class="alert">{c.title}: planned but missing</p>{/each}<details><summary>Effective voice & style <HelpTip term="Effective voice & style" text="The combined writing guidance that applies here, including inherited style and local voice or scene notes. Review it to understand the guidance available to the AI."/></summary><StyleControls card={element} onChanged={refresh} onLibrary={()=>libraryOpen=true} onRun={async()=>{await goto(`/n/${novelId}/chapters/${element.scene_id}`);}} onOpen={(c)=>{void goto(`/n/${novelId}/${c.type==='character'?'characters':c.type==='style'?'styles':'chapters'}/${c.id}`);}}/>{#if libraryOpen}<button on:click={()=>libraryOpen=false}>Close library</button><StyleLibrary card={element} onApplied={async()=>{libraryOpen=false;await refresh();}}/>{/if}</details>
 <details><summary>Cross-subplot links <HelpTip term="Cross-subplot links" text="Connect this scene to another scene, even in another plot. Depends on marks a dependency; Shares scene with connects related depictions of an event. Linked scene summaries help provide context."/></summary>{#each linked as l}<p>{l.title} · {l.type}<button on:click={()=>run(async()=>{await api(`/elements/${element.scene_id}/links`,'DELETE',l);await refresh();})}>Remove</button></p>{/each}<label>Target element<select bind:value={linkTarget}><option value="">Choose scene…</option><CardLinkOptions cards={allCards.filter(c=>c.type==='scene'&&c.id!==element.scene_id)}/></select></label><select aria-label="Link type" bind:value={linkType}><option value="depends_on">Depends on</option><option value="shares_scene_with">Shares scene with</option></select><button disabled={!linkTarget} on:click={()=>run(async()=>{await api(`/elements/${element.scene_id}/links`,'POST',{linked_element_id:linkTarget,type:linkType});await refresh();})}>Link</button></details></section>{/if}
 {#if review}<section><button class="back" on:click={()=>review=null}>← Close review</button><h2>{review.title}</h2><p>{review.cause_type} · {review.status} · {review.run_status} · {new Set(review.hunks.map((h:any)=>h.element_id)).size} elements · {review.hunks.length} hunks</p>{#if review.error}<p class="alert">{review.error}</p>{/if}<div class="actions"><button class="primary" disabled={busy||review.run_status==='running'||!review.hunks.some((h:any)=>h.status==='pending')} on:click={()=>run(()=>resolve('accept'))}>Accept all pending</button><button disabled={busy||review.run_status==='running'||!review.hunks.some((h:any)=>h.status==='pending')} on:click={()=>run(()=>resolve('reject'))}>Reject all pending</button>{#if ['interrupted','error','cancelled'].includes(review.run_status)}<button disabled={busy} on:click={()=>run(async()=>{await api(`/change-sets/${review.id}/retry`,'POST');await refresh();})}>Retry unfinished generation</button>{/if}{#if review.run_status==='running'}<button on:click={()=>run(async()=>{await api(`/change-sets/${review.id}/cancel`,'POST');await refresh();})}>Stop generation</button>{/if}{#if ['accepted','partially_accepted'].includes(review.status)}<button disabled={busy} on:click={()=>run(async()=>{const result=await api(`/change-sets/${review.id}/rollback`,'POST');notice=result.metadata_errors?.join('; ')||'Rolled back';await refresh();editorKey++;})}>Roll back accepted changes</button>{/if}</div>
 {#each [...new Set<string>(review.hunks.map((h:any)=>h.element_id))] as eid}{@const hs=review.hunks.filter((h:any)=>h.element_id===eid)}<article><h3>{hs[0]?.title}</h3><div class="actions"><button disabled={busy} on:click={()=>run(()=>resolve('accept',undefined,eid))}>Accept element</button><button disabled={busy} on:click={()=>run(()=>resolve('reject',undefined,eid))}>Reject element</button></div>{#each [...hs].sort((a,b)=>a.field==='summary'?-1:b.field==='summary'?1:a.start_offset-b.start_offset) as h}<div class="hunk"><h4>{h.field} · {h.status}</h4><p>{h.ai_note}</p>{#if h.warning}<p class="alert">{h.warning}</p>{/if}{#if h.context_before}<p class="context">{h.context_before}</p>{/if}<div class="comparison"><div><small>Before</small><pre>{h.before}</pre></div><div><small>After</small><pre>{h.after}</pre></div></div><div class="word-diff">{#each wordDiff(h.before,h.after) as [op,text]}{#if op===-1}<del>{text}</del>{:else if op===1}<ins>{text}</ins>{:else}{text}{/if}{/each}</div>{#if h.context_after}<p class="context">{h.context_after}</p>{/if}{#if h.status==='pending'}<button disabled={busy||review.run_status==='running'} on:click={()=>run(()=>resolve('accept',[h.id]))}>Accept hunk</button><button disabled={busy||review.run_status==='running'} on:click={()=>run(()=>resolve('reject',[h.id]))}>Reject hunk</button>{/if}</div>{/each}</article>{/each}</section>{/if}
 {#if workOpen||review}<section>{#if !review}<button class="back" on:click={()=>run(openOverview)}>← Plot overview</button>{/if}<h2>Proposals <HelpTip term="Proposals" text="AI suggestions waiting for review. Accepting applies the proposal; rejecting leaves the current content in place. Review a complete scene draft carefully because accepting it replaces the scene prose."/></h2>{#each work.proposals as p}<details class="proposal" open><summary>{p.kind==='prose'?'Scene draft':p.kind==='specs'?'Scene plans':p.kind==='turning_points'?'Turning points':'Premise'}</summary>{#if p.kind==='prose'}<label>Proposed prose<textarea rows="15" bind:value={proposals[p.id].text}></textarea></label>
 {:else if p.kind==='premise'}<label>Title<input bind:value={proposals[p.id].title}/></label><label>Premise <HelpTip term="Premise" text="A short description of what this plot is about: who is involved, what happens, and what is at stake. Approve it before adding scenes or asking for scene plans."/><textarea rows="5" bind:value={proposals[p.id].premise}></textarea></label><label>Theme <HelpTip term="Theme" text="The underlying idea or question this plot explores. For example: Does creating conscious minds give a civilization responsibility for their freedom? Optional; included in AI plot and scene context."/><input bind:value={proposals[p.id].theme}/></label><label>Start state <HelpTip term="Start state" text="The situation at the beginning of this plot: what the characters believe, want, or control. For example: The Shi-yul-pa depend on digital minds they treat as tools."/><textarea bind:value={proposals[p.id].start_state}></textarea></label><label>End state <HelpTip term="End state" text="The situation this plot should reach. Describe what has changed by its end; this gives the AI a destination when developing scenes."/><textarea bind:value={proposals[p.id].end_state}></textarea></label>
 {:else if p.kind==='turning_points'}{#each proposals[p.id].turning_points as tp,i}<label>Turning point {i+1}<textarea bind:value={tp.text}></textarea></label><button on:click={()=>moveProposal(proposals[p.id].turning_points,i,-1)}>↑</button><button on:click={()=>moveProposal(proposals[p.id].turning_points,i,1)}>↓</button><button on:click={()=>proposals[p.id].turning_points=proposals[p.id].turning_points.filter((_:any,j:number)=>j!==i)}>Remove</button>{/each}<button on:click={()=>proposals[p.id].turning_points=[...proposals[p.id].turning_points,{text:''}]}>Add turning point</button>
 {:else if p.kind==='specs'}{#each proposals[p.id].specs as spec,i}<article><label>Scene title<input bind:value={spec.title}/></label><label>Purpose <HelpTip term="Purpose" text="What happens in this scene and why it matters: a discovery, conflict, decision, or change. Used to guide AI drafting."/><textarea bind:value={spec.purpose}></textarea></label><label>Target words <HelpTip term="Target words" text="The approximate desired length of this scene. Guides AI drafting; it does not limit how much you can write."/><input type="number" min="1" bind:value={spec.target_length}/></label><label>Time marker <HelpTip term="Time marker" text="An optional free-text note about when this scene happens, such as Three days after the uprising or Meanwhile, on the 5th Planet. Included in AI scene context; it does not automatically reorder scenes."/><input bind:value={spec.time_marker}/></label>{#each spec.cards as c,j}<div class="hunk">{#if c.card_id}<label>Linked card<select bind:value={c.card_id}><CardLinkOptions cards={allCards.filter(c=>['character','group','setting','object','secret'].includes(c.type))}/></select></label>{:else}<label>New card name<input bind:value={c.name}/></label><label>Type<select bind:value={c.type}>{#each ['character','group','setting','object','secret'] as type}<option value={type}>{type}</option>{/each}</select></label>{/if}<label>Role <HelpTip term="Role" text="On stage means directly present or involved in this scene. Referenced means mentioned or relevant without being directly present. This helps choose the card context sent to the AI."/><select bind:value={c.role}><option value="on_stage">On stage</option><option value="referenced">Referenced</option></select></label>{#if c.type==='secret'||allCards.find(x=>x.id===c.card_id)?.type==='secret'}<label>Secret action <HelpTip term="Secret action" text="Track what this scene does with a secret: introduced brings it into the story, hinted offers clues, and revealed discloses it. No action leaves its disclosure unchanged."/><select bind:value={c.secret_action}><option value={null}>None</option><option value="introduced">Introduced</option><option value="hinted">Hinted</option><option value="revealed">Revealed</option></select></label>{/if}<button on:click={()=>spec.cards=spec.cards.filter((_:any,k:number)=>k!==j)}>Remove card</button></div>{/each}<button on:click={()=>spec.cards=[...spec.cards,{name:'',type:'character',role:'on_stage'}]}>Add new card</button><label>Link existing card <HelpTip term="Link existing card" text="Connect an existing character, group, location, object, or secret to this scene. Linked cards supply story facts to AI scene context."/><select value="" on:change={(ev)=>{if(ev.currentTarget.value)spec.cards=[...spec.cards,{card_id:ev.currentTarget.value,role:'on_stage'}];}}><option value="">Choose a card</option><CardLinkOptions cards={allCards.filter(c=>['character','group','setting','object','secret'].includes(c.type))}/></select></label><button on:click={()=>moveProposal(proposals[p.id].specs,i,-1)}>↑</button><button on:click={()=>moveProposal(proposals[p.id].specs,i,1)}>↓</button><button on:click={()=>proposals[p.id].specs=proposals[p.id].specs.filter((_:any,j:number)=>j!==i)}>Remove scene</button></article>{/each}<button on:click={()=>proposals[p.id].specs=[...proposals[p.id].specs,{title:'New element',purpose:'',target_length:1200,time_marker:'',cards:[]}]}>Add scene</button>{/if}
 <button class="primary" disabled={busy} on:click={()=>run(async()=>{await editor?.flush();await api(`/subplot-proposals/${p.id}/accept`,'POST',{payload:proposals[p.id]});await refresh();editorKey++;if(p.kind==='prose'){workOpen=false;review=null;editorTab='prose';}})}>{p.kind==='prose'?'Use this draft':'Accept proposal'}</button><button on:click={()=>run(async()=>{await api(`/subplot-proposals/${p.id}/reject`,'POST',{});await refresh();})}>Reject</button></details>{:else}<p class="note">No AI proposals waiting for review.</p>{/each}
 <h2>Card extraction <HelpTip term="Card extraction" text="Ask AI to identify characters, groups, locations, objects, secrets, and their mentions in the written scene. Review the proposed facts before creating or updating story cards."/></h2>{#each work.extractions as x}<article><h3>{allCards.find(c=>c.id===x.element_id)?.title}</h3>{#each x.payload.entities as ent,i}<div class="hunk"><b>{ent.name}</b> · {ent.type}{#if ent.merge_candidates?.length}<p>Possible merges: {ent.merge_candidates.map((id:string)=>allCards.find(c=>c.id===id)?.title||id).join(', ')}</p>{/if}<label>Action<select bind:value={extractionChoices[x.id][i].action}><option value="accept">Accept / edit</option><option value="merge">Merge into existing card</option><option value="ignore">Ignore</option></select></label><label>Name<input bind:value={extractionChoices[x.id][i].name}/></label><label>Proposed facts<textarea bind:value={extractionChoices[x.id][i].body}></textarea></label>{#if extractionChoices[x.id][i].action==='merge'}<label>Merge target<select bind:value={extractionChoices[x.id][i].target_id}><option value="">Choose a card</option><CardLinkOptions cards={allCards.filter(c=>c.type===ent.type)}/></select></label>{/if}</div>{/each}<p>{x.payload.mentions.length} validated mentions</p><button class="primary" disabled={busy} on:click={()=>run(async()=>{await api(`/extractions/${x.id}/resolve`,'POST',{items:extractionChoices[x.id]});await refresh();})}>Confirm extraction review</button><button on:click={()=>run(async()=>{await api(`/elements/${x.element_id}/extract`,'POST',{});await refresh();})}>Run extraction again</button></article>{:else}<p class="note">No card extractions waiting.</p>{/each}
 <h2>Change history</h2><label>Filter by card<select bind:value={filterCard} on:change={()=>run(refresh)}><option value="">All cards</option><CardLinkOptions cards={allCards.filter(c=>['character','group','setting','object','secret'].includes(c.type))}/></select></label>{#each work.change_sets as set}<button class="history" on:click={()=>run(async()=>{await editor?.flush();review=await api(`/change-sets/${set.id}`);})}>{set.title} · {new Date(set.created_at).toLocaleString()} · {set.status} · {set.run_status}</button>{/each}
 <details><summary>Context logs <HelpTip term="Context logs" text="Saved AI requests showing the instructions and story context sent for plot operations. Useful for understanding why a suggestion was made."/></summary>{#each work.requests as req}<button on:click={()=>run(async()=>{const r=await api(`/subplot-requests/${req.id}`);requestContext=JSON.stringify({...r,context:JSON.parse(r.context)},null,2);})}>{req.kind} · {req.status} · {new Date(req.created_at).toLocaleString()}</button>{/each}{#if requestContext}<pre class="context-log">{requestContext}</pre>{/if}</details></section>{/if}

 </fieldset></div>
 </div>
 {#if addingScene}<div class="modal-backdrop"><dialog open aria-label="Add scene"><h2>Add scene</h2><p class="note">{newSceneTpId ? 'Under turning point: '+subplot.turning_points.find((tp:any)=>tp.id===newSceneTpId)?.text : 'Directly under this plot'}</p><label>Scene title<input bind:value={elementTitle} placeholder="For example: Joss notices the power logs"/></label><label>What happens in this scene?<textarea bind:value={newScenePurpose}></textarea></label><details><summary>Place under a turning point or use an existing scene</summary><label>Turning point <HelpTip term="Turning point" text="A major event, decision, or discovery that changes the direction of the plot. Group scenes beneath it to show how that change happens. Scenes may also sit directly under the plot."/><select bind:value={newSceneTpId}><option value="">Directly under this plot</option>{#each subplot.turning_points as tp}<option value={tp.id}>{tp.text}</option>{/each}</select></label><label>Existing scene<select value="" on:change={(ev)=>{const id=ev.currentTarget.value;if(id)void run(async()=>{const e=await api(`/subplots/${selected}/elements`,'POST',{scene_id:id,turning_point_id:newSceneTpId||null});addingScene=false;await refresh();await pickElement(e);});}}><option value="">Choose scene…</option><CardLinkOptions cards={allCards.filter(c=>c.type==='scene')}/></select></label></details><div class="actions"><button class="primary" disabled={busy||!elementTitle.trim()} on:click={()=>run(async()=>{await flush();const e=await api(`/subplots/${selected}/elements`,'POST',{title:elementTitle,purpose:newScenePurpose,turning_point_id:newSceneTpId||null});elementTitle='';newScenePurpose='';addingScene=false;await refresh();await pickElement(e);editorTab='plan';})}>Create scene</button><button disabled={busy} on:click={()=>addingScene=false}>Cancel</button></div></dialog></div>{/if}
 {#if impactCard}<div class="modal-backdrop"><dialog open aria-modal="true" aria-label="Card impact" tabindex="-1"><h2>Impact · {allCards.find(c=>c.id===impactCard)?.title}</h2><p>Choose the passages to propose changes for. No prose changes until you accept the proposals.</p><label>Change-set title<input bind:value={impactTitle}/></label>{#each [...new Set<string>(impactRows.map(r=>r.subplot_title))] as group}<h3>{group}</h3>{#each impactRows.filter(r=>r.subplot_title===group) as row}<label class="impact-row"><input type="checkbox" value={row.element_id} bind:group={impactSelection}/><span><b>{row.title}</b> · {row.role} · {row.mentions.length} mentions<small>{row.snippet}</small></span></label>{/each}{/each}{#if !impactRows.length}<p>No indexed appearances yet.</p>{/if}<button class="primary" disabled={busy||!impactSelection.length} on:click={()=>run(proposeRewrite)}>Propose rewrites</button><button on:click={()=>impactCard=''}>Close</button></dialog></div>{/if}
</div>
<style>
 .reader-actions{justify-content:space-between;margin:0 0 18px}.reading{box-sizing:border-box;width:100%}.reading .reader-scene{border:0;padding:0;margin:0 0 32px}.reading .reader-scene:last-child{margin-bottom:0}
 .subplot-app{color:var(--ink);font-family:var(--ui)}.layout{display:block}.subplot-content{min-width:0}fieldset{min-width:0;border:0;padding:0;margin:0}
 .embedded-nav{display:flex;flex-direction:column;gap:6px;overflow-wrap:anywhere}.embedded-nav>button{text-align:left;width:100%;margin:0}.embedded-nav label{margin:0 0 6px;color:var(--dim);font-size:12px}.embedded-nav hr{width:100%;border:0;border-top:1px solid var(--line);margin:8px 0}.embedded-nav .scene-heading{margin:14px 2px 2px}.embedded-nav .scene-heading b{font:600 12px var(--ui);color:var(--dim)}
 h2,h3,h4{font-family:var(--serif);color:var(--ink)}h2{font-weight:500;font-size:26px;margin:0 0 6px}h3{font-size:20px;font-weight:500;margin:22px 0 8px}small,.context{color:var(--dim)}small{display:block;font-size:11.5px}
 section{padding:0 0 28px;margin:0 0 28px;border-bottom:1px solid var(--line)}section:last-child{border-bottom:0}
 label{display:block;font:600 12px/1.6 var(--ui);color:var(--dim);margin:14px 0 6px}
 input:not([type=checkbox]),textarea,select{box-sizing:border-box;width:100%;margin-top:4px;padding:10px 12px;border:1px solid var(--line);border-radius:var(--radius-s);background:var(--paper);color:var(--ink);font:400 14px/1.6 var(--ui)}
 input:not([type=checkbox]):focus,textarea:focus,select:focus{outline:2px solid var(--accent);outline-offset:-1px;border-color:transparent}
