 .active,.tp-nav.active{background:var(--accent-soft);border-color:transparent;color:var(--ink)}
 .outline-row{flex-wrap:nowrap;gap:2px}.outline-row>button:first-child{flex:1;text-align:left;min-height:46px;border-color:transparent;background:none;font-size:14px}.outline-row>button:first-child:hover{background:var(--soft);color:var(--ink)}.outline-row>button.active{background:var(--accent-soft)}
 .turning-point-row{display:flex;align-items:center;gap:6px}.turning-point-row>button{flex:1;min-width:0;overflow-wrap:anywhere}.turning-point-order{display:flex;flex-direction:column;gap:4px;flex-shrink:0}.turning-point-order button{padding:5px 10px;min-width:34px;min-height:32px}
 .tp-list{list-style:none;margin:12px 0 0;padding:0;display:flex;flex-direction:column;gap:6px;counter-reset:tp}
 .tp-list li{counter-increment:tp}.tp-review{margin:6px 0 6px 14px}.tp-review button{font-size:12px;padding:5px 12px}
 .tp-row{display:grid;grid-template-columns:28px 1fr;gap:2px 8px;width:100%;text-align:left;padding:12px 14px;border-radius:var(--radius);font:16px/1.5 var(--serif)}
 .tp-row::before{content:counter(tp);grid-row:span 2;font:500 18px var(--serif);color:var(--dim)}.tp-row small{display:flex;align-items:center;gap:8px;font-family:var(--ui)}
